import { readFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { z } from 'zod';

/**
 * Typed, validated application configuration.
 *
 * Every secret can be supplied either directly (`NAME`) or through a file
 * (`NAME_FILE`), which is how Docker secrets generated by the `init`
 * container are passed in. File values take precedence.
 */
export const APP_CONFIG = Symbol('APP_CONFIG');

const SECRET_KEYS = ['IMS_MASTER_KEY', 'JWT_ACCESS_SECRET', 'IMS_SETUP_TOKEN', 'DATABASE_URL', 'REDIS_URL'] as const;

const boolish = z
  .union([z.boolean(), z.string()])
  .transform((v) => (typeof v === 'boolean' ? v : ['1', 'true', 'yes', 'on'].includes(v.trim().toLowerCase())));

const envSchema = z.object({
  NODE_ENV: z.enum(['development', 'production', 'test']).default('production'),
  PORT: z.coerce.number().int().min(1).max(65535).default(3000),
  HOST: z.string().default('0.0.0.0'),
  IMS_PUBLIC_URL: z.string().url().optional(),
  DATABASE_URL: z.string().min(1, 'DATABASE_URL is required'),
  REDIS_URL: z.string().min(1, 'REDIS_URL is required'),
  IMS_MASTER_KEY: z.string().min(1, 'IMS_MASTER_KEY (or IMS_MASTER_KEY_FILE) is required'),
  JWT_ACCESS_SECRET: z.string().min(32, 'JWT_ACCESS_SECRET must be at least 32 characters'),
  IMS_SETUP_TOKEN: z.string().min(16).optional(),
  ACCESS_TOKEN_TTL_SEC: z.coerce.number().int().min(60).max(3600).default(900),
  DATA_DIR: z.string().default('/app/data'),
  LOG_LEVEL: z.enum(['error', 'warn', 'log', 'debug', 'verbose']).default('log'),
  TRUST_PROXY: z.string().default('loopback, uniquelocal'),
  COOKIE_SECURE: boolish.default(true),
  TELEGRAM_API_BASE: z.string().url().default('https://api.telegram.org'),
  IMS_VERSION: z.string().optional(),
});

export interface AppConfig {
  env: 'development' | 'production' | 'test';
  isProduction: boolean;
  version: string;
  port: number;
  host: string;
  publicUrl?: string;
  databaseUrl: string;
  redisUrl: string;
  /** 32-byte AES-256 master key. */
  masterKey: Buffer;
  jwtAccessSecret: string;
  setupToken?: string;
  accessTokenTtlSec: number;
  dataDir: string;
  logLevel: 'error' | 'warn' | 'log' | 'debug' | 'verbose';
  trustProxy: string;
  cookieSecure: boolean;
  telegramApiBase: string;
}

function readSecretFiles(env: NodeJS.ProcessEnv): Record<string, string | undefined> {
  const out: Record<string, string | undefined> = { ...env };
  for (const key of SECRET_KEYS) {
    const file = env[`${key}_FILE`];
    if (file) {
      if (!existsSync(file)) {
        throw new Error(`${key}_FILE points to a missing file: ${file}`);
      }
      out[key] = readFileSync(file, 'utf8').trim();
    }
  }
  return out;
}

function readVersion(explicit?: string): string {
  if (explicit) return explicit;
  for (const candidate of [resolve(__dirname, '../../../VERSION'), resolve(__dirname, '../../VERSION'), resolve(process.cwd(), 'VERSION')]) {
    if (existsSync(candidate)) return readFileSync(candidate, 'utf8').trim();
  }
  return '0.0.0-dev';
}

export function decodeMasterKey(raw: string): Buffer {
  const value = raw.trim();
  const key = /^[0-9a-fA-F]{64}$/.test(value) ? Buffer.from(value, 'hex') : Buffer.from(value, 'base64');
  if (key.length !== 32) {
    throw new Error('IMS_MASTER_KEY must decode to exactly 32 bytes (base64 or hex)');
  }
  return key;
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const parsed = envSchema.safeParse(readSecretFiles(env));
  if (!parsed.success) {
    const details = parsed.error.issues.map((i) => `  - ${i.path.join('.')}: ${i.message}`).join('\n');
    throw new Error(`Invalid configuration:\n${details}`);
  }
  const e = parsed.data;
  return {
    env: e.NODE_ENV,
    isProduction: e.NODE_ENV === 'production',
    version: readVersion(e.IMS_VERSION),
    port: e.PORT,
    host: e.HOST,
    publicUrl: e.IMS_PUBLIC_URL?.replace(/\/+$/, ''),
    databaseUrl: e.DATABASE_URL,
    redisUrl: e.REDIS_URL,
    masterKey: decodeMasterKey(e.IMS_MASTER_KEY),
    jwtAccessSecret: e.JWT_ACCESS_SECRET,
    setupToken: e.IMS_SETUP_TOKEN,
    accessTokenTtlSec: e.ACCESS_TOKEN_TTL_SEC,
    dataDir: resolve(e.DATA_DIR),
    logLevel: e.LOG_LEVEL,
    trustProxy: e.TRUST_PROXY,
    cookieSecure: e.COOKIE_SECURE,
    telegramApiBase: e.TELEGRAM_API_BASE.replace(/\/+$/, ''),
  };
}
